<?php
require __DIR__.'/../includes/staff_evaluation.php';
function assertion($condition,$message){if(!$condition)throw new RuntimeException($message);}
function fails(callable$fn,$message){try{$fn();}catch(RuntimeException$e){return;}throw new RuntimeException('Must reject '.$message);}
$cfg=se_defaults();$v=$cfg['template'];$v['active']=true;$v['effective']='2026-07-01';$v['number']=1;$v['id']='v1';$cfg['versions']=[$v];$cfg['assignments']['s1']=['user_id'=>'self','reviewer'=>'review','approver'=>'approve','profile'=>'regular','employment'=>'vienchuc','external'=>false];
$r=se_blank(['id'=>'s1','name'=>'Viên chức giả lập'],'2026-11',$cfg);$scores=[];foreach($r['criteria']as$c)$scores[$c['id']]=$c['max'];
$input=['revision'=>0,'form_schema'=>'2','scores'=>$scores,'common_summary'=>'Chấp hành quy định, phối hợp tốt.','task_summary'=>'Báo cáo tháng: 1 sản phẩm, đạt yêu cầu, đúng hạn.','strengths'=>'Hoàn thành công việc.','limits'=>'Không có hạn chế trong tháng.'];
$copy=$r;$submitted=se_transition($r,['id'=>'self'],'submit',$input);assertion($r===$copy,'Source remains unchanged');assertion($submitted['status']==='submitted'&&!$submitted['tasks'],'Single form works without duplicate task entry');assertion(count($submitted['history'])===1,'Single save audit');
$bad=$input;$bad['task_summary']='';fails(fn()=>se_transition($r,['id'=>'self'],'submit',$bad),'missing work summary');$bad=$input;$bad['strengths']='';fails(fn()=>se_transition($r,['id'=>'self'],'submit',$bad),'missing strengths');
$edited=se_transition($submitted,['id'=>'self'],'save_self',array_replace($input,['revision'=>1]));assertion($edited['status']==='draft','Pending self-edit returns to draft until re-sent');
$reviewed=se_transition($submitted,['id'=>'review'],'review',['revision'=>1,'scores'=>$scores,'reason'=>'Đã đối chiếu kết quả']);$locked=se_transition($reviewed,['id'=>'approve'],'approve',['revision'=>2,'scores'=>$scores,'reason'=>'Phê duyệt tháng']);
$year=se_year_summary(['2026-11'=>$locked],'2026-11','2026-12');assertion($year['missing']===['2026-12'],'Missing month disclosed');assertion($year['points']['total']===100.0,'Missing month not scored zero');assertion(str_contains(implode('',$year['common_summary']),$input['common_summary']),'Group A narrative feeds annual section 1');assertion(str_contains(implode('',$year['task_summary']),$input['task_summary']),'Group B narrative feeds annual section 2');assertion(str_contains(implode('',$year['strengths']),$input['strengths']),'Strengths feed annual section 4');assertion(str_contains(implode('',$year['limits']),$input['limits']),'Limits feed annual section 5');
$year=se_year_summary(['2026-11'=>$submitted],'2026-11','2026-11');assertion($year['points']['total']===null&&!$year['months'],'Only locked records feed year');
$legacy=$locked;unset($legacy['common_summary'],$legacy['task_summary']);$legacy['evidence_notes']=['A1'=>'Căn cứ cũ'];$legacy['tasks']=[['title'=>'Công việc cũ','product'=>'Báo cáo','quality'=>'Đủ','due'=>'2026-11-20','result'=>'Đã xong','completed'=>'2026-11-19']];$before=serialize($legacy);$sum=se_form_summary($legacy);assertion(str_contains($sum['common_summary'],'Căn cứ cũ')&&str_contains($sum['task_summary'],'Công việc cũ'),'Legacy record fallback');assertion(serialize($legacy)===$before,'Legacy records never rewritten');
$print=file_get_contents(__DIR__.'/../includes/staff_evaluation_month_print.php');assertion(str_contains($print,'SE_MONTH_PRINT_CONTEXT'),'Print cannot bypass controller authorization');assertion(!str_contains($print,'type="checkbox"'),'No annual classification imposed on monthly form');
echo "PASS monthly form: one submit, mandatory five contents, workflow lock, unchanged legacy, exact month-to-year field mapping and private print route\n";
